import React from "react";
import perfil from '../assets/icono_usuario.png';
import './HeaderPanel_A.css';


// Recibe la propiedad 'titulo'
export default function HeaderPanel({ titulo }) { 
    return(
        <header className="header-panel">
            {/* Usa la propiedad 'titulo' o un valor por defecto si no se pasa */}
            <h1>{titulo || "Panel de control"}</h1> 
            <div className="usuario">
                <a href="/perfil_admi"> 
                    <span>Admin.Gurama</span>
                    <img src={perfil} alt="perfil" />
                </a>
            </div>
        </header>
    );
}
